(async()=>{
  const C = await import('/js/flight/controls.js'), E = await import('/js/core/engine.js'), F = await import('/js/flight/fly.js'), A = await import('/js/flight/aircraft.js'), FL = await import('/js/flight/flow.js');
  const T = window.__T = {C, E, F, A, FL, log: []};
  T.pos = (id) => { const o = C.CTL.items[id]; const v = o.getWorldPosition(new o.position.constructor()); v.project(E.camera); return [(v.x + 1) / 2 * innerWidth, (1 - v.y) / 2 * innerHeight]; };
  T.side = (txt) => { const b = [...document.querySelectorAll('.act')].find(x => x.textContent.includes(txt)); if (!b) return [2, 2]; const r = b.getBoundingClientRect(); return [r.x + r.width / 2, r.y + r.height / 2]; };
  T.ans = (i) => { const b = document.querySelectorAll('#asklist .ans')[i]; if (!b) return [2, 2]; const r = b.getBoundingClientRect(); return [r.x + r.width / 2, r.y + r.height / 2]; };
  // the autopilot of the test: follow the real ground track a few seconds ahead, fly the best-glide speed, flare over the water
  T.fly = () => { const AC = A.AC, S = F.STICK; S.active = true; const V = AC.pos.constructor; let k = 0;
    E.onUpdate((dt) => {
      if (!F.FLY.on || F.FLY.touch) { if (F.FLY.touch) S.active = false; return; }
      const tg = A.sampleReal(Math.min(214, AC.t + 9), {pos: new V()}).pos;
      const brg = (Math.atan2(tg.x - AC.pos.x, -(tg.z - AC.pos.z)) * 180 / Math.PI + 360) % 360; let err = ((brg - AC.hdg + 540) % 360) - 180;
      const bankCmd = Math.max(-30, Math.min(30, err * 1.4)); S.x = Math.max(-1, Math.min(1, (bankCmd - AC.bank) / 12));
      const spd = AC.agl > 300 ? 205 : AC.agl > 80 ? 180 : 150;
      let y = Math.max(-0.6, Math.min(0.6, (AC.ias - spd) * 0.03 - (F.FLY.gam * 57.3 + 4) * 0.02));
      if (AC.agl < 30) { y = Math.max(-0.2, Math.min(1, (-AC.vs - 1.6) * 0.35 + (AC.pitch < 8 ? 0.15 : 0))); S.x = Math.max(-1, Math.min(1, -AC.bank / 6)); }
      S.y = y;
      if ((k += dt) > 5) { k = 0; T.log.push([Math.round(AC.t), Math.round(AC.alt), Math.round(AC.ias), Math.round(AC.hdg), Math.round(AC.bank), F.FLY.law]); }
    }); return 1; };
  // the radio: answer like the real captain
  T.radio = () => { setInterval(() => {
    const hint = document.getElementById('radiohint');
    if (hint && !hint.classList.contains('hidden')) dispatchEvent(new KeyboardEvent('keydown', {code: 'KeyT'}));
    const ask = document.getElementById('ask'); if (ask.classList.contains('hidden')) return;
    const q = document.getElementById('askq').textContent, n = document.querySelectorAll('#asklist .ans').length;
    const i = n === 3 ? 2 : (q.includes('تيتربورو؟') && n === 2) ? 1 : 0;
    if (!T.lastQ || T.lastQ !== q) { T.lastQ = q; setTimeout(() => { const b = document.querySelectorAll('#asklist .ans')[i]; b && b.click(); T.log.push(['ans', Math.round(A.AC.t), q.slice(0, 30), i]); }, 1500); }
  }, 300); return 1; };
  return 1;
})()
